namespace sv_1fb9801093b04d7682e5d37676b142f2.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds theme state
/// and notifies subscribers on change.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Components subscribe to this to call StateHasChanged.
    /// </summary>
    public event Action? OnChanged;

    /// <summary>
    /// Apply multiple changes and fire a single notification.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        var changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@using sv_1fb9801093b04d7682e5d37676b142f2.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

@using sv_1fb9801093b04d7682e5d37676b142f2.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeSvc.AccentColor;">
    @GetIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

