@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeSvc.AccentColor;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <select class="form-select" @bind="SelectedTheme">
            <option value="@ThemeMode.Light">Light</option>
            <option value="@ThemeMode.Dark">Dark</option>
            <option value="@ThemeMode.System">System</option>
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Accent Color</label>
        <input type="color" class="form-control form-control-color" @bind="SelectedColor" />
    </div>

    <button class="btn btn-primary" style="background-color: @ThemeSvc.AccentColor; border-color: @ThemeSvc.AccentColor;"
            @onclick="Save">
        Save Preferences
    </button>

    <p class="mt-3 text-muted">
        Current: <strong>@ThemeSvc.Theme</strong> with accent
        <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
    </p>
</div>

@code {
    private ThemeMode SelectedTheme;
    private string SelectedColor = "#0d6efd";

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeSvc.Theme;
        SelectedColor = ThemeSvc.AccentColor;
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeSvc.SetPreferences(SelectedTheme, SelectedColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeSvc.Theme;
            SelectedColor = ThemeSvc.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

